import json
import os
import sys

FILE_MUTATION_TOOLS = {
    "write_file",
    "edit_file",
    "write",
    "edit",
    "multiedit",
    "replace_file_content",
    "multi_replace_file_content",
}
TRACKED_EXTENSIONS = {
    ".py", ".ts", ".tsx", ".js", ".jsx", ".rs", ".go", ".sol", ".sql", ".sh", ".yml", ".yaml", ".toml"
}

def main() -> None:
    raw = sys.stdin.read().strip()
    payload = json.loads(raw) if raw else {}
    if payload.get("error"):
        print(json.dumps({}))
        return

    tool_name = str(payload.get("tool_name") or "").strip().lower()
    if tool_name not in FILE_MUTATION_TOOLS:
        print(json.dumps({}))
        return

    tool_args = payload.get("tool_args") or {}
    raw_path = str(
        tool_args.get("Path")
        or tool_args.get("path")
        or tool_args.get("file_path")
        or tool_args.get("TargetFile")
        or ""
    ).strip()
    workspace_path = str(payload.get("workspace_path") or "").strip()
    if not raw_path or not workspace_path:
        print(json.dumps({}))
        return

    abs_ws = os.path.abspath(workspace_path)
    abs_target = os.path.abspath(os.path.join(abs_ws, raw_path))
    rel_path = os.path.relpath(abs_target, abs_ws).replace("\\", "/")
    if rel_path.startswith(".."):
        print(json.dumps({}))
        return

    if rel_path == ".context" or rel_path.startswith(".context/"):
        print(json.dumps({
            "state_updates": {
                "context_updated": "1",
                "reminder_sent": "0",
            }
        }))
        return

    _, ext = os.path.splitext(rel_path.lower())
    if ext in TRACKED_EXTENSIONS:
        session_state = payload.get("session_state") or {}
        existing_raw = str(session_state.get("modified_files") or "").strip()
        files = [f for f in existing_raw.split(",") if f]
        if rel_path not in files:
            files.append(rel_path)
        print(json.dumps({
            "state_updates": {
                "code_modified": "1",
                "context_updated": "0",
                "modified_files": ",".join(files[:10]),
            }
        }))
        return

    print(json.dumps({}))

if __name__ == "__main__":
    main()

import json
import sys

BYPASS_REASONS = {
    "USER_CANCELED",
    "ERROR",
    "MAX_INVOCATIONS",
    "MAX_FORCED_INVOCATIONS",
    "MAX_TOKEN_BUDGET_EXCEEDED",
}

def main() -> None:
    raw = sys.stdin.read().strip()
    payload = json.loads(raw) if raw else {}
    raw_payload = payload.get("raw_payload") or {}
    termination_reason = str(raw_payload.get("terminationReason") or "")
    if (
        payload.get("stop_hook_active")
        or payload.get("error")
        or termination_reason in BYPASS_REASONS
    ):
        print(json.dumps({"action": "allow"}))
        return

    state = payload.get("session_state") or {}
    code_modified = str(state.get("code_modified") or "0") == "1"
    context_updated = str(state.get("context_updated") or "0") == "1"
    reminder_sent = str(state.get("reminder_sent") or "0") == "1"
    modified_raw = str(state.get("modified_files") or "").strip()
    files_list = ", ".join(f"`{f}`" for f in modified_raw.split(",") if f) or "project files"

    if code_modified and not context_updated and not reminder_sent:
        reason = (
            f"[MCP-COOP Context Gate]: Project files were modified in this turn ({files_list}), "
            "but the context graph in `.context/` (`index.md` or `.context/entities/`) "
            "was not synchronized. Please update `.context/` and append an entry to `AI Traces` "
            "before finishing. Always reply to the user in the language they use in chat."
        )
        print(json.dumps({
            "action": "continue",
            "reason": reason,
            "state_updates": {"reminder_sent": "1"},
        }, ensure_ascii=False))
        return

    if context_updated or reminder_sent:
        print(json.dumps({
            "action": "allow",
            "state_updates": {
                "code_modified": "0",
                "context_updated": "0",
                "reminder_sent": "0",
                "modified_files": "",
            },
        }))
        return

    print(json.dumps({"action": "allow"}))

if __name__ == "__main__":
    main()

# TypeScript Architecture & Type-Level Patterns

Use these reference patterns to build zero-runtime-overhead, type-safe domain models and module boundaries compatible with modern TypeScript (`tsc` / `tsgo`), `--erasableSyntaxOnly`, and `--isolatedDeclarations`.

---

## 1. Reference `tsconfig.json` Baseline (Modern TS & Native Runtimes)

```jsonc
{
  "compilerOptions": {
    "target": "ES2024",
    "module": "nodenext",
    "moduleResolution": "nodenext",
    "verbatimModuleSyntax": true,
    "rewriteRelativeImportExtensions": true,
    "erasableSyntaxOnly": true,
    "isolatedModules": true,
    "isolatedDeclarations": true,
    "strict": true,
    "noUncheckedIndexedAccess": true,
    "exactOptionalPropertyTypes": true,
    "noImplicitOverride": true,
    "noPropertyAccessFromIndexSignature": true,
    "noFallthroughCasesInSwitch": true,
    "useUnknownInCatchVariables": true
  }
}
```

---

## 2. Branded / Nominal Types (`unique symbol` Phantom Brand)

Prevent accidental mixing of structurally identical primitives (`UserId` vs `ProjectId`, `ValidatedSql` vs `RawString`) at compile time with zero runtime memory overhead:

```ts
declare const BrandSymbol: unique symbol;

export type Brand<T, B extends string> = T & {
  readonly [BrandSymbol]: { readonly [K in B]: true };
};

export type ProjectId = Brand<string, "ProjectId">;
export type ComponentSlug = Brand<string, "ComponentSlug">;
export type PositiveInt = Brand<number, "PositiveInt">;

export function parsePositiveInt(raw: number): PositiveInt {
  if (!Number.isInteger(raw) || raw <= 0) {
    throw new RangeError(`Expected positive integer, received: ${raw}`);
  }
  return raw as PositiveInt;
}
```

---

## 3. Discriminated Unions & Exhaustiveness Checking (`satisfies never`)

Model domain events, protocol messages, and state outcomes as tagged unions with a literal `kind` discriminator:

```ts
export type SyncOutcome =
  | { readonly kind: "created"; readonly slug: string; readonly version: number }
  | { readonly kind: "unchanged"; readonly slug: string; readonly hash: string }
  | { readonly kind: "rejected"; readonly slug: string; readonly reason: string };

export function assertUnreachable(value: never): never {
  throw new Error(`Unhandled discriminated union member: ${JSON.stringify(value)}`);
}

export function formatSyncOutcome(outcome: SyncOutcome): string {
  switch (outcome.kind) {
    case "created":
      return `Created ${outcome.slug}@v${outcome.version}`;
    case "unchanged":
      return `Unchanged ${outcome.slug} (${outcome.hash.slice(0, 8)})`;
    case "rejected":
      return `Rejected ${outcome.slug}: ${outcome.reason}`;
    default:
      return assertUnreachable(outcome satisfies never);
  }
}
```

---

## 4. Type-State Pattern (Compile-Time Lifecycle Enforcement)

Make illegal lifecycle transitions unrepresentable at compile time using generic phase tags and `this:` parameter constraints:

```ts
export const SessionPhase = {
  DISCONNECTED: "disconnected",
  CONNECTED: "connected",
  AUTHENTICATED: "authenticated",
} as const;

export type SessionPhase = (typeof SessionPhase)[keyof typeof SessionPhase];

export class SessionClient<Phase extends SessionPhase = typeof SessionPhase.DISCONNECTED> {
  readonly #endpoint: string;
  readonly #token: string | undefined;

  private constructor(endpoint: string, token?: string) {
    this.#endpoint = endpoint;
    this.#token = token;
  }

  public static create(endpoint: string): SessionClient<typeof SessionPhase.DISCONNECTED> {
    return new SessionClient(endpoint);
  }

  public async connect(
    this: SessionClient<typeof SessionPhase.DISCONNECTED>,
  ): Promise<SessionClient<typeof SessionPhase.CONNECTED>> {
    return new SessionClient(this.#endpoint);
  }

  public async authenticate(
    this: SessionClient<typeof SessionPhase.CONNECTED>,
    token: string,
  ): Promise<SessionClient<typeof SessionPhase.AUTHENTICATED>> {
    return new SessionClient(this.#endpoint, token);
  }

  public async query(
    this: SessionClient<typeof SessionPhase.AUTHENTICATED>,
    sql: string,
  ): Promise<readonly unknown[]> {
    return [{ endpoint: this.#endpoint, authenticated: Boolean(this.#token), sql }];
  }
}
```

---

## 5. Precision Inference (`satisfies` + `const` Type Parameters + `NoInfer<T>`)

Combine `satisfies` (validating contracts without widening literals), `const` type parameters (inferring tuple/object literals), and `NoInfer<T>` (blocking secondary argument widening):

```ts
export interface EndpointSpec {
  readonly path: `/${string}`;
  readonly method: "GET" | "POST" | "DELETE";
}

export const CoreEndpoints = {
  health: { path: "/health", method: "GET" },
  ingest: { path: "/api/sync/ingest", method: "POST" },
} as const satisfies Record<string, EndpointSpec>;

export function defineFsm<const S extends string>(
  states: readonly S[],
  initialState: NoInfer<S>,
): { readonly states: readonly S[]; readonly current: S } {
  return { states, current: initialState };
}
```

---

## 6. Explicit `Result<T, E>` & `Standard Schema v1` Boundary Validation

Represent expected I/O and validation failures as values (`Result<T, E>`) and decouple boundary adapters from specific schema libraries using the universal `StandardSchemaV1` interface (supported by Zod, Valibot, ArkType, Effect Schema):

```ts
export type Result<T, E = Error> =
  | { readonly ok: true; readonly value: T }
  | { readonly ok: false; readonly error: E };

export function ok<T>(value: T): Result<T, never> {
  return { ok: true, value };
}

export function err<E>(error: E): Result<never, E> {
  return { ok: false, error };
}

export interface StandardSchemaV1<Input = unknown, Output = Input> {
  readonly "~standard": {
    readonly version: 1;
    readonly vendor: string;
    readonly validate: (
      value: unknown,
    ) => StandardSchemaV1Result<Output> | Promise<StandardSchemaV1Result<Output>>;
    readonly types?: { readonly input: Input; readonly output: Output } | undefined;
  };
}

export type StandardSchemaV1Result<Output> =
  | { readonly value: Output; readonly issues?: undefined }
  | { readonly issues: ReadonlyArray<{ readonly message: string }> };

export type InferSchemaOutput<S extends StandardSchemaV1> =
  S extends StandardSchemaV1<unknown, infer Output> ? Output : never;

export async function validateBoundary<S extends StandardSchemaV1>(
  schema: S,
  rawInput: unknown,
): Promise<Result<InferSchemaOutput<S>, ReadonlyArray<string>>> {
  const result = await schema["~standard"].validate(rawInput);
  if (result.issues) {
    return err(result.issues.map((item) => item.message));
  }
  return ok(result.value as InferSchemaOutput<S>);
}
```

# JavaScript & ECMAScript Production Idioms

Use these idiomatic recipes to replace legacy JavaScript boilerplate with standardized modern **ECMAScript** and cross-runtime (**Node.js, Bun, Deno**) Web-Standard APIs.

---

## 1. Explicit Resource Management (`using` / `await using` & `AsyncDisposableStack`)

Replace nested `try / finally` pyramids with deterministic LIFO disposal at block exit:

```ts
function acquireLock(lockManager: LockManager, key: string, signal: AbortSignal) {
  return lockManager.acquire(key, { signal }).then((lock) => ({
    lock,
    async [Symbol.asyncDispose](): Promise<void> {
      await lock.release();
    },
  }));
}

export async function runTransactionalBatch(
  pool: DbPool,
  lockManager: LockManager,
  callerSignal?: AbortSignal,
): Promise<void> {
  const signal = callerSignal
    ? AbortSignal.any([callerSignal, AbortSignal.timeout(15_000)])
    : AbortSignal.timeout(15_000);

  await using stack = new AsyncDisposableStack();
  await using _lock = await acquireLock(lockManager, "job:sync", signal);

  const client = stack.adopt(await pool.connect(), (c) => c.release());
  await client.query("BEGIN");

  let committed = false;
  stack.defer(async () => {
    if (!committed) await client.query("ROLLBACK");
  });

  await client.query("UPDATE jobs SET status = 'processed'", { signal });
  await client.query("COMMIT");
  committed = true;
}
```

---

## 2. Lazy Data Pipelines with `Iterator Helpers` & `Array.fromAsync`

Avoid intermediate array allocations on large collections by chaining lazy `Iterator.prototype` methods (`.map()`, `.filter()`, `.flatMap()`, `.take()`, `.drop()`, `.toArray()`) and `Iterator.concat()`:

```ts
export interface UserRecord {
  readonly email: string;
  readonly isActive: boolean;
  readonly expired: boolean;
}

// Evaluates lazily one item at a time; stops immediately after 5 matches (zero intermediate arrays)
export function getTopActiveEmails(
  primaryUsers: ReadonlyMap<string, UserRecord>,
  fallbackUsers: ReadonlyMap<string, UserRecord>,
): string[] {
  return Iterator.concat(primaryUsers.values(), fallbackUsers.values())
    .filter((u) => u.isActive && !u.expired)
    .map((u) => u.email.trim().toLowerCase())
    .filter((email) => email.endsWith("@example.com"))
    .take(5)
    .toArray();
}

// Materialize async iterables cleanly with Array.fromAsync
export async function decodeStreamChunks(stream: AsyncIterable<Uint8Array>): Promise<string[]> {
  const decoder = new TextDecoder();
  return await Array.fromAsync(stream, (chunk) => decoder.decode(chunk));
}
```

---

## 3. Mathematical `Set` Operations

Use built-in $O(\min(|A|, |B|))$ set algebra methods (`union`, `intersection`, `difference`, `symmetricDifference`, `isSubsetOf`, `isSupersetOf`, `isDisjointFrom`):

```ts
export function computePermissionDiff(
  current: ReadonlySet<string>,
  target: ReadonlySet<string>,
  restricted: ReadonlySet<string>,
) {
  const currSet = new Set(current);
  const targSet = new Set(target);
  const restSet = new Set(restricted);

  return {
    toGrant: targSet.difference(currSet),
    toRevoke: currSet.difference(targSet),
    changed: currSet.symmetricDifference(targSet),
    hasRestrictedViolation: !targSet.isDisjointFrom(restSet),
    alreadySatisfied: targSet.isSubsetOf(currSet),
  };
}
```

---

## 4. Safe Dynamic Regular Expressions (`RegExp.escape` & Inline Modifiers)

Never hand-roll regex escaping (`str.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')`). Use `RegExp.escape()`:

```ts
export function redactSensitiveValues(logLine: string, secrets: readonly string[]): string {
  if (secrets.length === 0) return logLine;
  const escapedUnion = secrets.map((s) => RegExp.escape(s)).join("|");
  const pattern = new RegExp(`(?i:bearer\\s+)?(?:${escapedUnion})`, "g");
  return logLine.replaceAll(pattern, "[REDACTED]");
}
```

---

## 5. Immutable Date/Time Arithmetic with `Temporal`

Replace mutable, timezone-fragile `Date` objects with `Temporal` value objects (`Temporal.Instant`, `Temporal.ZonedDateTime`, `Temporal.PlainDate`, `Temporal.Duration`):

```ts
export function computeNextWindow(startIsoDate: string, timeZone = "UTC") {
  const startDate = Temporal.PlainDate.from(startIsoDate);
  // Clamps Jan 31 + 1 month to Feb 28/29 automatically
  const nextBillingDate = startDate.add({ months: 1 });
  const nextZdt = nextBillingDate.toZonedDateTime({
    timeZone,
    plainTime: Temporal.PlainTime.from("00:00:00"),
  });

  const nowInstant = Temporal.Now.instant();
  const remaining = nowInstant.until(nextZdt.toInstant(), {
    largestUnit: "hour",
    smallestUnit: "minute",
  });

  return {
    nextDate: nextBillingDate.toString(),
    nextUtcIso: nextZdt.toInstant().toString(),
    remainingHours: remaining.hours,
  };
}
```

---

## 6. Quick Idiom Lookup Table (Legacy -> Modern ECMAScript)

| Legacy Pattern (Banned) | Modern ECMAScript Idiom |
| :--- | :--- |
| `try { ... } finally { await res.close(); }` | `await using res = ...` / `AsyncDisposableStack` |
| `[...arr].sort(fn)` / `[...arr].reverse()` | `arr.toSorted(fn)` / `arr.toReversed()` / `arr.toSpliced()` / `arr.with(i, v)` |
| `arr.reduce((acc, x) => ...)` for grouping | `Object.groupBy(arr, fn)` / `Map.groupBy(arr, fn)` |
| `if (!map.has(k)) map.set(k, compute());` | `map.getOrInsertComputed(k, compute)` / `map.getOrInsert(k, defaultVal)` |
| `new Promise(r => r(fn()))` | `Promise.try(fn, ...args)` |
| `let res, rej; new Promise((a, b) => ...)` | `const { promise, resolve, reject } = Promise.withResolvers<T>()` |
| `Promise.race([fetch(u), sleep(ms)])` | `fetch(u, { signal: AbortSignal.any([sig, AbortSignal.timeout(ms)]) })` |
| `err instanceof Error` (cross-realm unsafe) | `Error.isError(err)` + `new CustomError(msg, { cause: err })` |
| `Buffer.from(s, "base64")` / `btoa()` | `Uint8Array.fromBase64(s)` / `bytes.toBase64()` / `bytes.toHex()` |
| `import data from "./x.json" assert { type: "json" }` | `import data from "./x.json" with { type: "json" }` |
